"""コメントに @claude があったとき、Claude のルーティン（clarify-reply スキル）を呼ぶ。

- 呼ぶのは、コメントした人がリポジトリの owner・member・collaborator のときだけ（公開リポジトリで、
  他の人のコメントに書かれた指示で Claude が動かないようにする）。
- ルーティンに渡すのは、コメントの URL だけ。本文は渡さない（Claude が API で読む）。
- Secrets（MENTION_ROUTINE_URL・MENTION_ROUTINE_TOKEN）が無ければ、警告を出すだけ。URL とトークンはログに出さない。
"""
from __future__ import annotations

import json
import os
import re
import sys
import time
import urllib.error
import urllib.request

ALLOWED = {"OWNER", "MEMBER", "COLLABORATOR"}
MENTION = re.compile(r"(?<![\w@])@claude\b", re.IGNORECASE)
RETRY_STATUSES = {429, 500, 502, 503, 529}


def log(msg: str) -> None:
    print(msg, flush=True)


def should_fire(event: dict) -> tuple[bool, str]:
    """(呼ぶか, 理由)。event は GitHub の issue_comment イベント。"""
    comment = event.get("comment") or {}
    if event.get("action") != "created":
        return False, "not created"
    if (comment.get("user") or {}).get("type") == "Bot":
        return False, "bot"
    if comment.get("author_association") not in ALLOWED:
        return False, "author is not owner/member/collaborator"
    body = comment.get("body") or ""
    if "<!-- claude" in body or "Generated by [Claude Code]" in body:
        return False, "claude's own comment"
    if not MENTION.search(body):
        return False, "no mention"
    return True, "ok"


def fire(text: str, attempts: int = 3) -> bool:
    url, token = os.environ.get("MENTION_ROUTINE_URL"), os.environ.get("MENTION_ROUTINE_TOKEN")
    if not (url and token):
        log("::warning::MENTION_ROUTINE_URL / MENTION_ROUTINE_TOKEN が未設定です。ルーティンは呼びません")
        return False
    req = urllib.request.Request(url, data=json.dumps({"text": text}).encode("utf-8"), method="POST", headers={
        "Authorization": "Bearer " + token,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json"})
    for i in range(attempts):
        try:
            with urllib.request.urlopen(req, timeout=60):
                log("mention routine: started")
                return True
        except urllib.error.HTTPError as e:
            if e.code in RETRY_STATUSES and i < attempts - 1:
                time.sleep(10 * (i + 1))
                continue
            log(f"mention routine: not started (HTTP {e.code})")
            return False
        except Exception as e:  # noqa: BLE001
            log(f"mention routine: not started ({type(e).__name__})")
            return False
    return False


def main() -> int:
    with open(os.environ["GITHUB_EVENT_PATH"], encoding="utf-8") as f:
        event = json.load(f)
    ok, reason = should_fire(event)
    if not ok:
        log(f"skip: {reason}")
        return 0
    comment = event["comment"]
    fire(f"comment={comment['html_url']}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
